('Issued Items Against Work Order','2013-05-03 17:48:46.000000','2018-02-13 04:56:57.040163','Administrator','Administrator',0,3,'Issued Items Against Work Order','Work Order',NULL,'Yes','Manufacturing','Query Report',NULL,0,0,0,0,0,'select\n    ste.work_order as \"Work Order:Link/Work Order:120\",\n    ste.posting_date as \"Issue Date:Date:140\",\n    ste_item.item_code as \"Item Code:Link/Item:120\",\n	ste_item.description as \"Description::150\",\n	ste_item.transfer_qty as \"Qty:Float:100\",\n	ste_item.stock_uom as \"UOM:Link/UOM:80\",\n	ste_item.amount as \"Amount:Currency:120\",\n	ste_item.serial_no as \"Serial No:Link/Serial No:80\",\n	ste_item.s_warehouse as \"Source Warehouse:Link/Warehouse:120\",\n	ste_item.t_warehouse as \"Target Warehouse:Link/Warehouse:120\",\n	wo.production_item as \"Finished Goods:Link/Item:120\", \n	ste.name as \"Stock Entry:Link/Stock Entry:120\",\n	ste.company as \"Company:Link/Company:\",\n	(select bin.projected_qty from `tabBin` bin \n			where  bin.item_code= ste_item.item_code and bin.warehouse= ste_item.s_warehouse) as \"Projected Quantity as Source:Float:200\"\nfrom	`tabStock Entry` ste, `tabStock Entry Detail` ste_item, `tabWork Order` wo\nwhere\n	ifnull(ste.work_order, \'\') != \'\' and ste.name = ste_item.parent \n	and ste.work_order = wo.name and ste.docstatus = 1\n	and ste.purpose = \'Material Transfer for Manufacture\'\norder by ste.posting_date, ste.work_order, ste_item.item_code',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Item Balance (Simple)','2018-02-17 19:52:16.370979','2018-02-19 12:03:53.902167','Administrator','Administrator',0,0,'Item Balance (Simple)','Bin',NULL,'Yes','Stock','Query Report',NULL,0,0,0,0,0,'select a.item_code as \"Item:Link/Item:120\",\n	  a.item_name as \"Item Name::150\",\n	  a.item_group as \"Item Group:Link/Item Group:120\",\n	  a.brand as \"Brand:Link/Brand:120\",\n	  a.description as \"Description::150\",\n	  b.warehouse as \"Warehouse:Link/Warehouse:120\",\n	  b.actual_qty as \"Balance Qty:Float:140\"\n from `tabItem` a left join `tabBin` b\n ON a.item_code = b.item_code',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
