('Maintenance Schedules','2013-05-06 14:25:21.000000','2014-06-29 08:18:17.144598','Administrator','Administrator',0,1,'Maintenance Schedules','Maintenance Schedule',NULL,'Yes','Support','Query Report',NULL,0,0,0,0,0,'SELECT\n    ms_sch.scheduled_date as \"Schedule Date:Date:120\",\n	ms_sch.item_code as \"Item Code:Link/Item:120\",\n	ms_sch.item_name as \"Item Name::120\",\n	ms_sch.serial_no as \"Serial No::120\",\n	ms_sch.sales_person as \"Sales Person::120\",\n	ms.customer_name as \"Customer:Link/Customer:120\",\n	ms.address_display as \"Customer Address::120\",\n	ms_item.sales_order as \"Sales Order:Link/Sales Order:120\",\n	ms.company as \"Company:Link/Company:120\"\n	\nFROM\n	`tabMaintenance Schedule` ms, \n    `tabMaintenance Schedule Detail` ms_sch, \n    `tabMaintenance Schedule Item` ms_item\nWHERE\n	ms.name = ms_sch.parent and ms.name = ms_item.parent and ms.docstatus = 1\nORDER BY\n	ms_sch.scheduled_date asc, ms_sch.item_code asc',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Material Requests for which Supplier Quotations are not created','2013-08-09 12:20:58.000000','2017-02-24 20:05:31.066151','Administrator','Administrator',0,3,'Material Requests for which Supplier Quotations are not created','Material Request',NULL,'Yes','Stock','Query Report',NULL,0,0,0,0,0,'select \n    mr.name as \"Material Request:Link/Material Request:120\",\n    mr.transaction_date as \"Date:Date:100\",\n	mr_item.item_code as \"Item Code:Link/Item:120\",\n	mr_item.qty as \"Qty:Float:100\",\n	mr_item.item_name as \"Item Name::150\",\n	mr_item.description as \"Description::200\",\n	mr.company as \"Company:Link/Company:\"\nfrom\n	`tabMaterial Request` mr, `tabMaterial Request Item` mr_item\nwhere\n	mr_item.parent = mr.name\n	and mr.material_request_type = \"Purchase\"\n	and mr.docstatus = 1\n	and mr.status != \"Stopped\"\n	and not exists(select name from `tabSupplier Quotation Item` where material_request=mr.name)\norder by mr.transaction_date asc',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
